old<-file.path(base,'side_day1_day3_combined_ROC_age_20261010_v1/results')
paths<-c(file.path(old,'ROC_coordinates.csv'),file.path(old,'Three_model_AUC_age.csv'),file.path(base,'prediction_day1_day3_20261009_v1/results/paired_comparisons.csv'),file.path(base,'prediction_day1_day3_20261009_v1/results/performance.csv'))
sha<-function(p)digest::digest(file=p,algo='sha256',serialize=FALSE)
stopifnot(all(file.exists(paths)));before<-vapply(paths,sha,character(1));allcurves<-read.csv(paths[1]);alltab<-read.csv(paths[2])
models<-c('D1','D3');keys<-c('ALL',paste0('L0',1:5));colors<-c(D1='#9ACCF3',D3='#FF6268');types<-c(D1='dashed',D3='solid')
curves<-allcurves[allcurves$model %in% models,];tab<-alltab[alltab$model %in% models,];stopifnot(nrow(tab)==12,nrow(alltab)==18)
en<-c('Overall','Neonates (≤28 d)','Infants (>28 d–<1 y)','Children 1–4 y','Children 5–9 y','Children 10–14 y')
model_labels<-c(D1='Clinical + day 1',D3='Clinical + day 3');plots<-list();checks<-list()
for(g in 1:6){
  tt<-tab[tab$group==keys[g],];cc<-curves[curves$group==keys[g],];cc$model<-factor(cc$model,levels=models)
  stopifnot(nrow(tt)==2,length(unique(tt$N))==1,length(unique(tt$deaths))==1)
  legends<-list()
  for(mm in 1:2){m<-models[mm];v<-cc[cc$model==m,];t<-tt[tt$model==m,];a<-sum(diff(v$FPR)*(head(v$TPR,-1)+tail(v$TPR,-1))/2)
    stopifnot(abs(a-t$AUC)<1e-12,all(v[1,c('FPR','TPR')]==0),all(tail(v[c('FPR','TPR')],1)==1),all(diff(v$FPR)>=0),all(diff(v$TPR)>=0))
    checks[[length(checks)+1]]<-data.frame(group=keys[g],model=m,AUC=a,source_AUC=t$AUC,difference=a-t$AUC,endpoints_monotonic=TRUE)
    legends[[mm]]<-data.frame(model=m,y=3-mm,label=sprintf('%s: AUC %.3f (%.3f–%.3f)',model_labels[m],t$AUC,t$conditional_ci_low,t$conditional_ci_high))
  }
  ttl<-sprintf('%s %s\n ',LETTERS[g],en[g])
  top<-ggplot(cc,aes(FPR,TPR,colour=model,linetype=model))+geom_abline(intercept=0,slope=1,colour='#43A79A',linetype='dotted',linewidth=.45)+geom_path(linewidth=.95)+scale_colour_manual(values=colors)+scale_linetype_manual(values=types)+scale_x_continuous(limits=c(0,1),breaks=seq(0,1,.2),expand=c(0,0))+scale_y_continuous(limits=c(0,1),breaks=seq(0,1,.2),expand=c(0,0))+coord_equal(expand=FALSE)+labs(title=ttl,x='False-positive rate (1 − specificity)',y='Sensitivity')+theme_classic(base_size=11.5,base_family='Arial')+theme(legend.position='none',plot.title=element_text(face='bold',size=11.5,lineheight=1.15),axis.title.x=element_text(size=10),axis.title.y=element_text(angle=90),plot.margin=margin(8,9,3,9))
  ll<-do.call(rbind,legends);ll$model<-factor(ll$model,levels=models)
  bottom<-ggplot(ll,aes(colour=model,linetype=model))+geom_segment(aes(x=.01,xend=.09,y=y,yend=y),linewidth=.9)+geom_text(aes(x=.12,y=y,label=label),colour='black',hjust=0,size=3.1,family='Arial')+scale_colour_manual(values=colors)+scale_linetype_manual(values=types)+coord_cartesian(xlim=c(0,1),ylim=c(.4,2.6),expand=FALSE,clip='off')+theme_void()+theme(legend.position='none',plot.margin=margin(1,8,6,8))
  plots[[g]]<-top/bottom+plot_layout(heights=c(1,.14))
}
fig<-wrap_plots(plots,ncol=3)+plot_annotation(title=NULL,subtitle=NULL,caption=paste('Both models predict subsequent in-hospital death in the same 72-hour landmark cohort.', 'Age panels evaluate common whole-cohort models. Intervals are conditional on saved out-of-fold scores.',sep='\n'),theme=theme(text=element_text(family='Arial'),plot.title=element_text(size=16,face='bold'),plot.subtitle=element_text(size=11),plot.caption=element_text(size=9.5,hjust=0)))
